import json, hashlib

lower=(3,3,3,0,0); upper=(5,5,5,5,5); N=5

def wt(p): return sum(p)
def conj(p): return tuple(sum(x>=c for x in p) for c in range(1,N+1))
def parts_between(d):
    out=[]
    def rec(i,prev,cur,left):
        if i==N:
            if left==0: out.append(tuple(cur))
            return
        lo=lower[i]; hi=min(prev,upper[i],left)
        for x in range(hi,lo-1,-1): rec(i+1,x,cur+[x],left-x)
    rec(0,upper[0],[],d)
    return out
def hstrip(lam,mu):
    if any(lam[i]>mu[i] for i in range(N)): return False
    cl,cm=conj(lam),conj(mu)
    return all(0<=cm[c]-cl[c]<=1 for c in range(N))
def eye(n): return [[int(i==j) for j in range(n)] for i in range(n)]
def mm(A,B):
    if not A: return []
    return [[sum(A[i][k]*B[k][j] for k in range(len(B))) for j in range(len(B[0]))] for i in range(len(A))]
def smith_witness(M):
    m=len(M); n=len(M[0]) if m else 1
    if m==0: return [],[],[[1]],[]
    A=[r[:] for r in M]; U=eye(m); V=eye(n)
    def rs(i,j):
        A[i],A[j]=A[j],A[i]; U[i],U[j]=U[j],U[i]
    def cs(i,j):
        for X in (A,V):
            if X is A:
                for r in range(m): X[r][i],X[r][j]=X[r][j],X[r][i]
            else:
                for r in range(n): X[r][i],X[r][j]=X[r][j],X[r][i]
    def ra(i,j,q):
        for c in range(n): A[i][c]+=q*A[j][c]
        for c in range(m): U[i][c]+=q*U[j][c]
    def ca(i,j,q):
        for r in range(m): A[r][i]+=q*A[r][j]
        for r in range(n): V[r][i]+=q*V[r][j]
    k=0
    while k<m and k<n:
        pos=None
        for i in range(k,m):
            for j in range(k,n):
                if A[i][j] and (pos is None or abs(A[i][j])<abs(A[pos[0]][pos[1]])): pos=(i,j)
        if pos is None: break
        rs(k,pos[0]); cs(k,pos[1])
        while True:
            changed=False
            for i in range(k+1,m):
                if A[i][k]:
                    q=A[i][k]//A[k][k]
                    ra(i,k,-q)
                    if abs(A[i][k])<abs(A[k][k]) and A[i][k]: rs(i,k)
                    changed=True; break
            if changed: continue
            for j in range(k+1,n):
                if A[k][j]:
                    q=A[k][j]//A[k][k]
                    ca(j,k,-q)
                    if abs(A[k][j])<abs(A[k][k]) and A[k][j]: cs(j,k)
                    changed=True; break
            if changed: continue
            bad=None
            for i in range(k+1,m):
                for j in range(k+1,n):
                    if A[i][j] % A[k][k] != 0: bad=(i,j); break
                if bad: break
            if bad:
                ra(k,bad[0],1)
                continue
            break
        if A[k][k]<0:
            for c in range(n): A[k][c]=-A[k][c]
            for c in range(m): U[k][c]=-U[k][c]
        k+=1
    return U,A,V,[A[i][i] for i in range(min(m,n)) if A[i][i]!=0]
def det_bareiss(A):
    n=len(A)
    if n==0:return 1
    B=[r[:] for r in A]; sign=1; prev=1
    for k in range(n-1):
        if B[k][k]==0:
            q=next((i for i in range(k+1,n) if B[i][k]),None)
            if q is None:return 0
            B[k],B[q]=B[q],B[k];sign=-sign
        pivot=B[k][k]
        for i in range(k+1,n):
            for j in range(k+1,n): B[i][j]=(B[i][j]*pivot-B[i][k]*B[k][j])//prev
        prev=pivot
        for i in range(k+1,n): B[i][k]=0
    return sign*B[-1][-1]
def record(d):
    cols=parts_between(d); rows=[]; labels=[]
    for t in range(1,6):
        for lam in parts_between(d-t):
            row=[int(hstrip(lam,mu)) for mu in cols]
            rows.append(row); labels.append([t,list(lam)])
    U,D,V,diag=smith_witness(rows)
    ok=(mm(mm(U,rows),V)==D) if rows else (D==[])
    du=det_bareiss(U) if rows else 1; dv=det_bareiss(V)
    positive=all(x>0 for x in diag); divides=all(diag[i+1]%diag[i]==0 for i in range(len(diag)-1))
    return {"degree":d,"columns":[list(x) for x in cols],"rowLabels":labels,"M":rows,"U":U,"V":V,"D":D,"shape":[len(rows),len(cols)],"rank":len(diag),"smithNonzero":diag,"quotientFreeRank":len(cols)-len(diag),"torsionInvariantFactors":[x for x in diag if x>1],"detU":du,"detV":dv,"verifiedUMVeqD":ok,"smithPositive":positive,"smithDivisibility":divides}
recs=[record(d) for d in range(9,26)]
# Explicitly validate the required boundary convention.
boundary={"M9":"0x1 []","D9":"0x1 []","U9":"I_0 []","V9":[[1]],"detU9":1,"detV9":1,"verifiedUMVeqD":recs[0]["verifiedUMVeqD"]}
out={"input":{"lower":list(lower),"upper":list(upper),"degrees":list(range(9,26)),"hDegrees":[1,2,3,4,5]},"ordering":"columns and sources: reverse lexicographic padded partitions; rows: hDegree ascending then source order","pieriCriterion":"lambda_i<=mu_i (i=1..5) and 0<=mu'_c-lambda'_c<=1 (c=1..5)","boundary":boundary,"witnesses":recs,"allWitnessesVerified":all(x['verifiedUMVeqD'] and abs(x['detU'])==1 and abs(x['detV'])==1 and x['smithPositive'] and x['smithDivisibility'] for x in recs)}
s=json.dumps(out,separators=(',',':'))
print(s)
print('OUTPUT_SHA256='+hashlib.sha256(s.encode()).hexdigest())
